WITH ra AS (
  SELECT ST_PointOnSurface(geom) AS p FROM residential_areas WHERE name='东方城' ORDER BY id LIMIT 1
), v AS (
  SELECT wv.id, wv.component, wv.in_main FROM walk_vertices wv, ra
  ORDER BY wv.geom <-> ra.p LIMIT 1
), dd AS (
  SELECT * FROM pgr_drivingDistance('SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges', (SELECT id FROM v), 500, directed => false)
), reach AS (
  SELECT node FROM dd
)
SELECT (SELECT id FROM v) AS start_vid, (SELECT component FROM v) AS comp, (SELECT in_main FROM v) AS in_main,
       (SELECT count(*) FROM reach) AS reachable_vertices,
       (SELECT count(*) FROM bus_stops b WHERE EXISTS (SELECT 1 FROM walk_vertices wv JOIN reach r ON r.node=wv.id WHERE wv.geom <-> b.geom < 0.0005)) AS stops_near_reachable,
       (SELECT min(ST_Distance(b.geom::geography, ra.p::geography)) FROM bus_stops b, ra) AS nearest_straight_m
FROM ra;

WITH ra AS (
  SELECT ST_PointOnSurface(geom) AS p FROM residential_areas WHERE name='东方城' ORDER BY id LIMIT 1
), v AS (
  SELECT wv.id FROM walk_vertices wv, ra ORDER BY wv.geom <-> ra.p LIMIT 1
), dd AS (
  SELECT node, agg_cost FROM pgr_drivingDistance('SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges', (SELECT id FROM v), 500, directed => false)
), stops AS (
  SELECT b.id, b.name, b.geom, (SELECT wv.id FROM walk_vertices wv WHERE wv.in_main ORDER BY wv.geom <-> b.geom LIMIT 1) AS vid
  FROM bus_stops b, ra
  WHERE ST_DWithin(b.geom::geography, ra.p::geography, 800)
)
SELECT s.id, s.name, s.vid, d.agg_cost AS walk_m, ST_Distance(s.geom::geography, ra.p::geography) AS straight_m
FROM stops s LEFT JOIN dd d ON d.node = s.vid
ORDER BY walk_m NULLS LAST, straight_m
LIMIT 10;

