WITH ra AS (
  SELECT ST_PointOnSurface(geom) AS pt FROM residential_areas WHERE name='香格里拉花园' LIMIT 1
), sv AS (
  SELECT v.id FROM walk_vertices v, ra WHERE v.in_main ORDER BY v.geom <-> ra.pt LIMIT 1
), dd AS (
  SELECT node, agg_cost FROM sv, LATERAL pgr_drivingDistance('SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges', sv.id, 300, directed => false) d
), kg AS (
  SELECT p.id, p.name, (SELECT v.id FROM walk_vertices v WHERE v.in_main ORDER BY v.geom <-> p.geom LIMIT 1) AS vid
  FROM pois p WHERE p.subtype='kindergarten'
)
SELECT kg.name, round(dd.agg_cost) AS walk_m
FROM kg JOIN dd ON dd.node = kg.vid
ORDER BY walk_m LIMIT 5

